alter table public.menu_items drop constraint menu_items_category_check;
alter table public.menu_items add constraint menu_items_category_check check (category in ('new','grills','sides','appetizers','mini','drinks','soups','salads','cold-starters','hot-starters'));
alter table public.menu_items drop constraint menu_items_price_check;
alter table public.menu_items add constraint menu_items_price_check check (price between 0 and 1000000 and (price > 0 or not available));
update public.menu_items set published = false where id not in ('menu-1', 'menu-2', 'menu-3', 'dish-22', 'menu-5', 'dish-23', 'dish-25', 'dish-33', 'menu-9', 'dish-15', 'menu-11', 'dish-18', 'dish-17', 'menu-14', 'dish-3', 'dish-4', 'dish-5', 'menu-18', 'menu-19', 'menu-20', 'menu-21', 'dish-14', 'menu-23', 'dish-10', 'dish-13', 'menu-26', 'dish-7', 'dish-16', 'menu-29', 'menu-30', 'menu-31', 'menu-32', 'dish-36', 'menu-34', 'menu-35', 'menu-36', 'menu-37', 'menu-38', 'menu-39', 'menu-40', 'menu-41', 'menu-42', 'dish-40', 'dish-43', 'menu-45');
on conflict (id) do update set category=excluded.category, name_ar=excluded.name_ar, name_en=excluded.name_en, description_ar=excluded.description_ar, description_en=excluded.description_en, calories=excluded.calories, position=excluded.position, published=true;
